/* CSS to set a full-page custom background */
body {
    /* Replace the URL with the path to your uploaded image */
    background-image: url(https://i.pinimg.com/originals/e9/06/67/e906672b7091e259d638b588bccf7e75.jpg);
    
    /* Make the background cover the entire page */
    background-size: cover;
    
    /* Keep the image centered while scrolling */
    background-position: center center;
    background-repeat: no-repeat;
    background-attachment: fixed;
    
    /* Optional: Add a subtle overlay to improve readability */
    /* background-color: rgba(0,0,0,0.3); */
    
    /* Apply a smooth transition for hover or dynamic effects if needed */
    transition: background 0.5s ease-in-out;
}

/* Optional: Customize font color and sections to make them readable */
h1, h2, h3, p, a, span, div {
    color: #ffffff; /* Change to match background for clarity */
    text-shadow: 0 1px 3px rgba(0,0,0,0.5);
}
